package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"runtime"
	"sync"
)

// ---------- 1. 基于 sync.Pool 的安全 Buffer 池 ----------

const maxBufSize = 64 * 1024 // 超过 64KB 的 buffer 不回池，避免内存滞留

var bufPool = sync.Pool{
	New: func() any {
		return new(bytes.Buffer) // 返回空指针对象，零值即可用
	},
}

// getBuf 取出 buffer 并保证是干净状态
func getBuf() *bytes.Buffer {
	b := bufPool.Get().(*bytes.Buffer)
	b.Reset() // 关键：清掉上次遗留的数据，防止数据泄漏
	return b
}

// putBuf 归还 buffer；只在 buf 仍然“可控”时才回收
func putBuf(b *bytes.Buffer) {
	if b.Cap() > maxBufSize {
		return // 超大对象直接丢弃，交给 GC，避免池子膨胀
	}
	bufPool.Put(b)
}

// ---------- 2. 业务示例：JSON 序列化 + 手写日志行 ----------

type Event struct {
	UserID uint64            `json:"user_id"`
	Action string            `json:"action"`
	Attrs  map[string]string `json:"attrs"`
}

func renderEvent(e Event) (string, error) {
	buf := getBuf()
	defer putBuf(buf) // 无论成功失败都归还

	// 复用 buffer 做 JSON 编码，避免 encoder 内部反复 make []byte
	enc := json.NewEncoder(buf)
	if err := enc.Encode(e); err != nil {
		return "", err
	}
	// buf.Bytes() 末尾带 '\n'，这里手动追加前缀
	out := make([]byte, 0, buf.Len()+8)
	out = append(out, "EVENT "...)
	out = append(out, buf.Bytes()...)
	return string(out), nil // string(out) 会复制，安全：返回值不指向 buf
}

// ---------- 3. 对比：带池 vs 不带池（可用 -benchmem 观察差异） ----------

func noPoolRender(e Event) (string, error) {
	var b bytes.Buffer // 每次调用都新分配（且大概率逃逸到堆）
	if err := json.NewEncoder(&b).Encode(e); err != nil {
		return "", err
	}
	return "EVENT " + b.String(), nil
}

func main() {
	e := Event{UserID: 42, Action: "login", Attrs: map[string]string{"ip": "10.0.0.1"}}

	for i := 0; i < 3; i++ {
		s, err := renderEvent(e)
		if err != nil {
			panic(err)
		}
		fmt.Print(s)
	}

	// 演示：GC 会清空 sync.Pool，Put 进去的对象不一定还能 Get 到
	var demo = sync.Pool{New: func() any { return "fresh" }}
	demo.Put("cached")
	fmt.Println("before GC:", demo.Get())
	demo.Put("cached")
	runtime.GC() // 触发 GC，池中缓存可能被清空
	fmt.Println("after  GC:", demo.Get()) // 输出 fresh（New 创建）

	// 观察逃逸分析：go build -gcflags="-m" main.go
	fmt.Println("noPool result:", must(noPoolRender(e)))
}

func must(s string, err error) string {
	if err != nil {
		panic(err)
	}
	return s
}

/*
编译与性能观测命令：
  go build -gcflags="-m -m" main.go   # 查看逃逸分析详细原因
  go test -bench=. -benchmem -cpuprofile=cpu.out -memprofile=mem.out
  go tool pprof -alloc_objects mem.out
*/

